"""Team trial forms. Missing inputs stay missing; no automated confirmation."""
PILOTS_CSS = r"""
.pi-grid>section,.pi-grid>aside{min-width:0}.pi-panel{min-width:0;max-width:100%;box-sizing:border-box}.pi-scroll{max-width:100%}.pi-row>div{min-width:120px}
.pi-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.pi-head h1{margin:8px 0}.pi-head p{max-width:65ch;color:var(--muted,#64748b)}
.pi-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:24px}.pi-panel{border:1px solid var(--line,#e2e8f0);border-radius:12px;padding:22px;background:var(--surface,#fff);margin-bottom:20px}.pi-panel h2{margin-top:0}.pi-panel label{display:block;margin:12px 0 6px}.pi-panel input:not([type=checkbox]),.pi-panel textarea,.pi-panel select{width:100%;box-sizing:border-box}.pi-panel textarea{min-height:86px}.pi-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:12px 0}.pi-row label{margin:0;display:inline-flex;align-items:center;gap:6px}.pi-period{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:8px;margin:12px 0}.pi-table{width:100%;border-collapse:collapse}.pi-table td,.pi-table th{text-align:left;border-bottom:1px solid var(--line,#e2e8f0);padding:12px 8px;vertical-align:top}.pi-scroll{overflow:auto}.pi-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:65vh;overflow:auto;font-size:12px}.pi-missing{border-left:3px solid #c97929;padding:8px 16px;background:#fff9ed}.pi-stat{font-size:28px;font-weight:650;margin:8px 0}.pi-note{line-height:1.7;color:var(--muted,#64748b)}.pi-actions{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.pi-state{display:inline-block;background:#eef3fb;color:#315d98;border-radius:6px;padding:4px 9px}.pi-target{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:8px}.pi-record{border-top:1px solid var(--line,#e2e8f0);padding:12px 0}.pi-panel [hidden]{display:none!important}@media(max-width:760px){.pi-grid{grid-template-columns:1fr}.pi-head{display:block}.pi-period,.pi-target{grid-template-columns:1fr 1fr}.pi-panel{padding:16px}.pi-table{min-width:600px}}
"""

PILOTS_JS = r"""
const PI={page:null};
const piState={draft:'草稿',frozen:'协议已冻结',active:'记录中',ended:'已结束记录'};
const piDuty={requirements:'需求',development:'研发',testing:'测试',delivery:'交付',operations:'运维'};
const piActivity={analysis:'分析',implementation:'实施',testing:'测试',handoff:'交接',rework:'返工',operations:'运维',other:'其他'};
function piLive(v){return PI.page===v&&v.route===location.hash&&v.epoch===ACCESS.epoch&&!ACCESS.blocked&&v.host.isConnected}
function piKey(v){return ['webuddy.pilot',location.origin,ACCESS.base,v.actor,v.project,v.id||'new'].join('|')}
function piLoad(key){try{return JSON.parse(sessionStorage.getItem(key)||'null')}catch(e){return null}}
function piPut(key,value){try{if(value===null)sessionStorage.removeItem(key);else sessionStorage.setItem(key,JSON.stringify(value))}catch(e){throw apiErr('浏览器无法保存草稿或原请求，请先备份输入再重试。')}}
function piOptions(values,current,empty='请选择'){return `<option value="">${h(empty)}</option>`+Object.entries(values).map(([k,label])=>`<option value="${h(k)}" ${k===current?'selected':''}>${h(label)}</option>`).join('')}
function piField(name,label,value='',area=false){area=area||!['model_budget_cny','followup_on'].includes(name);return `<label>${h(label)}${area?`<textarea data-pi-field="${h(name)}">${h(value)}</textarea>`:`<input data-pi-field="${h(name)}" value="${h(value)}">`}</label>`}
function piEmpty(){return {title:'',goal:'',application_reference:'',baseline_reference:'',comparison:'',inclusion_rule:'',participants:[],periods:[{id:'baseline',name:'对照阶段',kind:'baseline',start_on:'',end_on:''},{id:'trial1',name:'第一周期',kind:'trial',start_on:'',end_on:''},{id:'trial2',name:'第二周期',kind:'trial',start_on:'',end_on:''}],tasks:[],targets:{},followup_on:'',exit_rule:'',missing_rule:'',model_budget_cny:null}}
async function vPilots(project,id='',ticket='',revision=''){
 project=project||S.proj;if(!project||project==='*'){$('#main').innerHTML='<h1>团队试点</h1><p>请先进入一个具体项目。</p><a class="btn" href="#/projects">选择项目</a>';return}
 const host=$('#main');host.innerHTML='<p>正在读取团队试点…</p>';const v={host,route:location.hash,epoch:ACCESS.epoch,project,id:id==='new'?'':id,ticket,revision};PI.page=v;
 const list=await get('/api/projects/'+encodeURIComponent(project)+'/pilots');if(!piLive(v))return;v.list=list;v.actor=list.actor;setProj(project);S.scope=project;ls.set('tmh.scope',project);paintSel();
 if(!id){host.innerHTML=`<div class="pi-head"><div><a href="#/projects/${h(encodeURIComponent(project))}">返回项目</a><h1>团队试点</h1><p>在同一组真实任务上记录协作、投入和质量。先补齐协议，再由参与者本人确认。</p></div>${list.can_manage?`<a class="btn primary" href="#/pilots/${h(encodeURIComponent(project))}/new">创建试点草稿</a>`:''}</div><div class="pi-panel">${list.items.length?list.items.map(x=>`<article class="pi-record"><span class="pi-state">${h(piState[x.state])}</span><h2><a href="#/pilots/${h(encodeURIComponent(project))}/${h(x.id)}/${h(encodeURIComponent(v.ticket||''))}">${h(x.protocol.title||'未命名草稿')}</a></h2><p>${h(x.protocol.goal||'尚未填写试点目标')}</p><span class="sub">修订 ${x.revision} · 固定任务 ${x.protocol.tasks.length} 项</span></article>`).join(''):'<h2>还没有团队试点</h2><p>真实资料可以逐步补齐。保存草稿不会启动执行或产生人工确认。</p>'}</div>`;return}
 v.data=v.id?await get('/api/projects/'+encodeURIComponent(project)+'/pilots/'+encodeURIComponent(v.id)+(revision?'?revision='+encodeURIComponent(revision):'')):{id:'',actor:v.actor,version:0,revision:0,protocol_hash:'',state:'draft',protocol:piEmpty(),can_manage:list.can_manage,missing:[],confirmations:[],events:[]};if(!piLive(v))return;piPaint(v);
}
function piDraft(v){const x=piLoad(piKey(v)+'|draft');return x?.base===v.data.protocol_hash?x.protocol:v.data.protocol}
function piPreserve(original,value){return typeof original==='string'&&original.replace(/\r\n?/g,'\n')===value?original:value}
function piSpec(v){const form=v.host.querySelector('#piProtocol'),p=piEmpty(),original=piDraft(v);form.querySelectorAll('[data-pi-field]').forEach(x=>p[x.dataset.piField]=piPreserve(original[x.dataset.piField],x.value));p.model_budget_cny=p.model_budget_cny||null;p.comparison=form.querySelector('[data-pi-comparison]').value;
 p.participants=[...form.querySelectorAll('[data-pi-user]')].filter(x=>x.querySelector('input[data-pi-join]').checked).map(x=>({user:x.dataset.piUser,duties:[...x.querySelectorAll('[data-pi-duty]:checked')].map(y=>y.dataset.piDuty)}));
 p.periods=[...form.querySelectorAll('[data-pi-period]')].map(x=>({id:x.dataset.piPeriod,name:piPreserve(original.periods.find(p=>p.id===x.dataset.piPeriod)?.name,x.querySelector('[data-pi-name]').value),kind:x.querySelector('[data-pi-kind]').value,start_on:x.querySelector('[data-pi-start]').value,end_on:x.querySelector('[data-pi-end]').value}));
 p.tasks=[...form.querySelectorAll('[data-pi-task]')].filter(x=>x.querySelector('input[type=checkbox]').checked).map(x=>({ticket:x.dataset.piTask,period:x.querySelector('select').value,complexity:piPreserve(original.tasks.find(t=>t.ticket===x.dataset.piTask)?.complexity,x.querySelector('[data-pi-complexity]').value)}));
 p.targets={};form.querySelectorAll('[data-pi-target]').forEach(x=>p.targets[x.dataset.piTarget]={metric:x.querySelector('[data-pi-metric]').value,direction:x.querySelector('select').value,value:x.querySelector('[data-pi-value]').value,unit:x.querySelector('[data-pi-unit]').value});return p;
}
function piPeriod(x){return `<div class="pi-period" data-pi-period="${h(x.id)}"><label>名称<textarea data-pi-name rows="1">${h(x.name)}</textarea></label><label>类型<select data-pi-kind>${piOptions({baseline:'历史基线',control:'并行对照',trial:'试验周期'},x.kind)}</select></label><label>开始<input type="date" data-pi-start value="${h(x.start_on)}"></label><label>结束<input type="date" data-pi-end value="${h(x.end_on)}"></label></div>`}
function piPaint(v){if(!piLive(v))return;const d=v.data,p=JSON.parse(JSON.stringify(piDraft(v)));if(!p.periods.length&&d.state==='draft')p.periods=piEmpty().periods;const selected=new Map(p.tasks.map(x=>[x.ticket,x])),periods=Object.fromEntries(p.periods.map(x=>[x.id,x.name||x.id])),historical=d.id&&d.revision!==d.current_revision;
 v.host.innerHTML=`<div class="pi-head"><div><a href="#/pilots/${h(encodeURIComponent(v.project))}">团队试点 / ${h(v.project)}</a><h1>${h(d.protocol.title||'准备团队试点')}</h1><p>协议、本人投入和来源放在同一处。缺失不当作零，记录结束不表示组织收益已被证明。</p></div><span class="pi-state">${h(piState[d.state])} · 修订 ${d.revision}</span></div><div id="piNotice" role="status"></div><div class="pi-grid"><section>${d.id&&d.state!=='draft'?'<details class="pi-panel"><summary>查看完整试点协议 / 另存修订</summary>':'<section class="pi-panel">'}<h2>试点协议</h2><p class="pi-note">${historical?'历史协议原文只读；已开始的历史版本仍可登记投入或明确结束。':d.state==='draft'?'先保存草稿，再由参与者本人阅读并确认。':'修改会另存为新草稿，原协议与记录继续保留。'}</p><form id="piProtocol"><fieldset ${!d.can_manage||historical?'disabled':''} style="border:0;padding:0;min-width:0">
 ${piField('title','试点名称',p.title)}${piField('goal','希望改善什么，以及质量不能退化的地方',p.goal,true)}${piField('application_reference','项目版本依据（人工声明）',p.application_reference)}${piField('baseline_reference','对照来源与可比性说明',p.baseline_reference,true)}<label>对照方式<select data-pi-comparison>${piOptions({before_after:'前后对照',parallel:'并行对照'},p.comparison)}</select></label>${piField('inclusion_rule','任务纳入规则与完整范围',p.inclusion_rule,true)}
 <h3>参与者与职责</h3><p class="pi-note">至少两位不同个人，覆盖五类职责；不能由经理代确认。</p>${[...new Set([...v.list.members,...p.participants.map(x=>x.user)])].map(user=>{const part=p.participants.find(x=>x.user===user);return `<div data-pi-user="${h(user)}"><label><input type="checkbox" data-pi-join ${part?'checked':''}> ${h(user)}${v.list.members.includes(user)?'':'（当前不可用）'}</label><div class="pi-row">${Object.entries(piDuty).map(([k,label])=>`<label><input type="checkbox" data-pi-duty="${k}" ${part?.duties.includes(k)?'checked':''}>${label}</label>`).join('')}</div></div>`}).join('')}
 <h3>观察日历（中国时间）</h3><p class="pi-note">至少一个对照阶段、两个分离的试验周期。冻结应早于首个试验日。</p><div id="piPeriods">${p.periods.map(piPeriod).join('')}</div><button type="button" id="piAddPeriod">增加阶段</button>
 <h3>固定任务全集</h3><p class="pi-note">以下包含本项目所有状态的任务；退出保留在报告分母中。纳入完整性仍需参与者核对。</p><div class="pi-scroll"><table class="pi-table"><thead><tr><th>纳入与任务</th><th>阶段</th><th>复杂度依据</th></tr></thead><tbody>${[...new Map([...v.list.tickets.map(t=>[v.project+'-'+t.num,{key:v.project+'-'+t.num,title:t.title,status:t.status}]),...p.tasks.filter(t=>!v.list.tickets.some(x=>v.project+'-'+x.num===t.ticket)).map(t=>[t.ticket,{key:t.ticket,title:'当前不可用，原记录仍保留',status:'unknown'}])]).values()].map(t=>{const x=selected.get(t.key);return `<tr data-pi-task="${h(t.key)}"><td><label><input type="checkbox" ${x?'checked':''}>${h(t.key)} · ${h(t.title)}</label><span class="sub">${h(t.status)}</span></td><td><select>${piOptions(periods,x?.period)}</select></td><td><textarea data-pi-complexity rows="1" aria-label="${h(t.key)} 复杂度">${h(x?.complexity||'')}</textarea></td></tr>`}).join('')}</tbody></table></div>
 <h3>预先约定的数值目标</h3>${Object.entries({quality:'质量约束',improvement:'改善目标',cost_shift:'全角色负担上界'}).map(([key,label])=>{const t=p.targets[key]||{};return `<label>${label}</label><div class="pi-target" data-pi-target="${key}"><input data-pi-metric aria-label="${label} 指标" placeholder="指标" value="${h(t.metric||'')}"><select aria-label="${label} 方向">${piOptions({at_most:'不高于',at_least:'不低于'},t.direction)}</select><input data-pi-value inputmode="decimal" aria-label="${label} 数值" placeholder="数值" value="${h(t.value??'')}"><input data-pi-unit aria-label="${label} 单位" placeholder="单位" value="${h(t.unit||'')}"></div>`}).join('')}
 ${piField('model_budget_cny','模型预算上限（元，未知留空；不授权调用）',p.model_budget_cny||'')}${piField('followup_on','后续观察终点 YYYY-MM-DD',p.followup_on)}${piField('exit_rule','退出规则',p.exit_rule,true)}${piField('missing_rule','缺失与未完成如何处理',p.missing_rule,true)}<div class="pi-actions"><button class="primary" type="submit">${d.id?'另存协议修订':'保存草稿'}</button></div></fieldset></form>${d.id&&d.state!=='draft'?'</details>':'</section>'}
 ${d.report?piReport(v):''}${d.id&&['active','ended'].includes(d.state)?piLaborForm(v):''}</section><aside><section class="pi-panel"><h2>当前准备情况</h2>${d.id?`<p class="pi-note">协议版本 ${d.revision}<br>来源 ${d.source_current?'与登记一致':'已变化或不可核对'}</p>`:''}${d.missing.length?`<div class="pi-missing"><ul>${d.missing.map(x=>`<li>${h(x)}</li>`).join('')}</ul></div>`:`<p>${d.id&&d.state!=='draft'?'协议字段已齐；当前记录仍不证明组织收益。':'草稿可逐步补齐；冻结前会检查全部必填项。'}</p>`}<h3>本人确认</h3>${d.confirmations.map(x=>`<p>${h(x.user)} · ${x.confirmed?'已确认本版本':x.stale?'旧确认已失效':'尚未本人确认'}</p>`).join('')}<div class="pi-actions">${d.id&&!historical&&d.state==='draft'&&d.confirmations.some(x=>x.user===v.actor)?'<button data-pi-act="confirm">本人确认此版本</button>':''}${d.id&&d.can_manage?`<button data-pi-act="freeze" ${historical||d.state!=='draft'||d.missing.length||d.confirmations.some(x=>!x.confirmed)?'disabled':''}>冻结协议</button><button data-pi-act="start" ${historical||d.state!=='frozen'?'disabled':''}>开始记录</button><button data-pi-act="end" ${d.state!=='active'?'disabled':''}>结束记录</button>`:''}</div><p class="pi-note">不会自动启动模型、采用知识、验收或关单。</p></section>${d.id?`<section class="pi-panel"><h2>版本与完整记录</h2><label>查看协议修订<select id="piRevision">${d.revisions.map(x=>`<option value="${x.revision}" ${x.revision===d.revision?'selected':''}>修订 ${x.revision} · ${h(piState[x.state])}</option>`).join('')}</select></label><div class="pi-actions"><button id="piJSON">下载 JSON</button><button id="piMD">下载 Markdown</button></div><details><summary>完整协议、来源与事件</summary><pre>${h(JSON.stringify(d,null,2))}</pre></details></section>`:''}</aside></div>`;
 const form=v.host.querySelector('#piProtocol');form.oninput=()=>{if(piLive(v))piPut(piKey(v)+'|draft',{base:d.protocol_hash,protocol:piSpec(v)})};form.onsubmit=e=>{e.preventDefault();return piWrite(v,{action:d.id?'revise':'create',protocol:piSpec(v)})};v.host.querySelector('#piAddPeriod').onclick=()=>{const spec=piSpec(v);spec.periods.push({id:'period_'+crypto.randomUUID().replaceAll('-',''),name:'',kind:'trial',start_on:'',end_on:''});piPut(piKey(v)+'|draft',{base:d.protocol_hash,protocol:spec});piPaint(v)};
 v.host.querySelectorAll('[data-pi-act]').forEach(x=>x.onclick=()=>piWrite(v,{action:x.dataset.piAct}));if(d.id){v.host.querySelector('#piRevision').onchange=e=>location.hash='#/pilots/'+encodeURIComponent(v.project)+'/'+v.id+'/'+encodeURIComponent(v.ticket||'')+'/'+e.target.value;v.host.querySelector('#piJSON').onclick=()=>piDownload(v,'json');v.host.querySelector('#piMD').onclick=()=>piDownload(v,'md')}
 piBindLabor(v);piPending(v);
}
function piNotice(v,text){if(piLive(v)){const host=v.host.querySelector('#piNotice');host.textContent=text;host.className='pi-panel';}}
function piPending(v){const pending=piLoad(piKey(v)+'|pending');if(!pending||!piLive(v))return;v.host.querySelectorAll('form button,[data-pi-act]').forEach(x=>x.disabled=true);const n=v.host.querySelector('#piNotice');n.className='pi-panel';n.innerHTML='<p>上次提交结果尚未确认。请沿用原请求核对，避免重复登记。</p><button id="piRetry">用原请求核对结果</button>';n.querySelector('button').onclick=()=>piWrite(v,null)}
async function piWrite(v,change){if(!piLive(v)||v.busy)return;const key=piKey(v)+'|pending';let saved=piLoad(key);if(saved&&change){piNotice(v,'请先核对原请求结果。');piPending(v);return}if(!saved){saved={actor:v.actor,path:'/api/projects/'+encodeURIComponent(v.project)+'/pilots'+(v.id?'/'+v.id:''),body:{...change,expected_actor:v.actor,version:v.data.version,revision:v.data.revision,protocol_hash:v.data.protocol_hash,request_id:crypto.randomUUID()}};try{piPut(key,saved)}catch(e){piNotice(v,e.message);return}}
 if(saved.actor!==v.actor||saved.body.expected_actor!==v.actor){piNotice(v,'身份已变化，旧请求不可提交。');return}v.busy=true;v.host.querySelectorAll('form button,[data-pi-act],#piRetry').forEach(x=>x.disabled=true);
 try{const receipt=await post(saved.path,saved.body);if(!receipt?.receipt?.event_id||!receipt.id)throw apiErr('服务器回执不完整，请沿用原请求核对。');piPut(key,null);piPut(piKey(v)+'|draft',null);if(saved.body.action==='labor')piPut(piKey(v)+'|labor',null);if(!piLive(v))return;if(!v.id){location.hash='#/pilots/'+encodeURIComponent(v.project)+'/'+receipt.id;return}piNotice(v,'动作已登记，正在重新读取当前状态。');try{const fresh=await get('/api/projects/'+encodeURIComponent(v.project)+'/pilots/'+v.id+(v.revision?'?revision='+encodeURIComponent(v.revision):''));if(piLive(v)){v.data=fresh;piPaint(v)}}catch(e){piNotice(v,'动作已登记。当前详情读取失败，请刷新读取；无需重新提交。');}}
 catch(e){if(e.status&&e.status<500){piPut(key,null);piNotice(v,e.message+' 输入仍保留，请核对最新版本。');const n=v.host.querySelector('#piNotice'),b=document.createElement('button');b.textContent='保留输入，重新读取';b.onclick=()=>vPilots(v.project,v.id||'new',v.ticket,v.revision);n.appendChild(b)}else{piNotice(v,e.message);piPending(v)}}finally{v.busy=false}
}
function piReport(v){const r=v.data.report;return `<section class="pi-panel"><h2>阶段记录</h2><p class="pi-note">截至 ${h(new Date(r.observed_at).toLocaleString('zh-CN'))} · 本协议已知 ${r.event_range.count} 条事件。后补或更正生成新截点。</p><p class="pi-note">${h(r.notice)}</p><p class="pi-missing">填报完整性仍未知：有记录不代表全部投入已报齐。阶段外记录不填补阶段内缺失。</p><div class="pi-row"><div><div class="pi-stat">${r.task_count}</div>固定任务</div><div><div class="pi-stat">${r.recorded_minutes}</div>已申报分钟</div><div><div class="pi-stat">${r.missing_labor_cells}</div>阶段内未填职责项</div></div>${!r.task_count?'<p class="pi-missing">任务全集尚未登记，暂不能计算投入覆盖。</p>':''}<p>阶段外投入 ${r.outside_period_minutes} 分钟 · 事后登记 ${r.retrospective_minutes} 分钟（可与阶段外重合）</p><p>实际模型费用：未知 · 组织收益：尚未核证</p><div class="pi-scroll"><table class="pi-table"><thead><tr><th>固定任务 / 阶段</th><th>原运行与退出</th><th>等待</th><th>验收观察</th><th>本人投入</th></tr></thead><tbody>${r.tasks.map(t=>`<tr><td>${h(t.ticket)}<br>${h(r.periods.find(p=>p.id===t.period)?.name||t.period)} · ${h(t.complexity)}<br>${t.current_available?h(t.current_ticket.status):'当前来源不可用'}</td><td>${t.runs.length} 次运行，${t.runs.filter(x=>x.status!=='done').length} 次非成功<br>${t.exits.length?'已退出，仍计入全集':'未登记退出'}</td><td>${t.waiting.seconds===null?'未知':h(Math.round(t.waiting.seconds/60))+' 分钟'}<br>${h({unknown:'未登记等待',unknown_invalid_timestamps:'时间来源无法核对',observed_open:'等待尚未结束',recorded:'已记录区间'}[t.waiting.status]||'无法核对')}</td><td>${h({not_accepted:'未验收',unknown:'无法核对',pending:'观察未成熟',matured:'已达观察期'}[t.acceptance.status])}</td><td>${t.coverage.map(x=>`${h(x.user)} / ${h(piDuty[x.duty])}：${x.in_period_minutes===null?'阶段内未填':h(x.in_period_minutes)+' 分钟'}${x.outside_period_minutes===null?'':'；阶段外 '+h(x.outside_period_minutes)+' 分钟'}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div><h3>有效投入记录</h3>${r.labor.map(e=>`<article class="pi-record"><strong>${h(e.actor)} · ${h(e.payload.ticket)} · ${e.payload.minutes} 分钟</strong><p>${h(e.payload.note)}</p><p class="sub">${h(e.payload.started_at)}${e.payload.retrospective?' · 事后登记':''}${e.payload.outside_period?' · 阶段外记录':''}</p>${e.actor===v.actor?`<button data-pi-correct="${e.id}">追加更正</button>`:''}</article>`).join('')||'<p>尚无投入记录。没有记录不代表零投入。</p>'}</section>`}
function piLaborForm(v){const p=v.data.protocol,part=p.participants.find(x=>x.user===v.actor);if(!part&&!v.data.can_manage)return '';return `<section class="pi-panel" id="piLaborPanel"><h2>登记本人实际投入</h2><p class="pi-note">作者为 ${h(v.actor)}。等待时间另列，劳动重叠会被拒绝。更正追加历史，不覆盖原记录。</p>${part?`<form id="piLabor"><input type="hidden" name="supersedes"><label>固定任务<select name="ticket">${piOptions(Object.fromEntries(p.tasks.map(x=>[x.ticket,x.ticket])),v.ticket)}</select></label><label>本人职责<select name="duty">${piOptions(Object.fromEntries(part.duties.map(x=>[x,piDuty[x]])))}</select></label><label>活动<select name="activity">${piOptions(piActivity)}</select></label><label>开始时间（含时区）<input name="started_at" placeholder="2026-10-25T09:00:00+08:00" required></label><label>实际分钟<input name="minutes" type="number" min="0" max="1440" step="1" required></label><label>完整说明<textarea name="note" required></textarea></label><label>证据引用（每行一项）<textarea name="evidence_refs"></textarea></label><label>零投入原因<input name="zero_reason"></label><label>阶段外记录原因<textarea name="outside_reason"></textarea></label><button class="primary">登记本人投入</button></form>`:'<p>当前账号未在参与者职责中；不能代录投入。</p>'}${v.data.can_manage?`<hr><h3>任务退出</h3><form id="piExit"><label>固定任务<select name="ticket">${piOptions(Object.fromEntries(p.tasks.map(x=>[x.ticket,x.ticket])))}</select></label><label>退出原因<textarea name="reason" required></textarea></label><button>登记退出，保留分母</button></form>`:''}</section>`}
function piBindLabor(v){const f=v.host.querySelector('#piLabor');if(f){const draft=piLoad(piKey(v)+'|labor');if(draft){f._original=draft._original;Object.entries(draft).forEach(([k,val])=>{if(f.elements[k])f.elements[k].value=val})}f.oninput=()=>piPut(piKey(v)+'|labor',{...Object.fromEntries(new FormData(f)),_original:f._original});f.onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(f));x.minutes=Number(x.minutes);for(const k of ['note','zero_reason','outside_reason'])x[k]=piPreserve(f._original?.[k],x[k]);const refs=f._original?.evidence_refs;x.evidence_refs=refs&&piPreserve(refs.join('\n'),x.evidence_refs)===refs.join('\n')?refs:x.evidence_refs.split('\n').filter(x=>x.trim());x.supersedes=x.supersedes?Number(x.supersedes):null;return piWrite(v,{action:'labor',labor:x})};v.host.querySelectorAll('[data-pi-correct]').forEach(b=>b.onclick=()=>{const e=v.data.report.labor.find(e=>e.id===Number(b.dataset.piCorrect));f._original=e.payload;Object.entries(e.payload).forEach(([k,val])=>{if(f.elements[k])f.elements[k].value=Array.isArray(val)?val.join('\n'):val??''});f.elements.supersedes.value=e.id;f.oninput();f.scrollIntoView({behavior:'smooth',block:'start'})})}const exit=v.host.querySelector('#piExit');if(exit)exit.onsubmit=e=>{e.preventDefault();return piWrite(v,{action:'exit',...Object.fromEntries(new FormData(exit))})}}
function piDownload(v,kind){if(!piLive(v))return;const raw=JSON.stringify(v.data,null,2),fence='`'.repeat(Math.max(3,...(raw.match(/`+/g)||[]).map(x=>x.length+1))),text=kind==='json'?raw:'# 团队试点完整阶段记录\n\n报告截点：'+v.data.report.observed_at+'\n\n固定任务 '+v.data.report.task_count+' 项；已申报 '+v.data.report.recorded_minutes+' 分钟；阶段外 '+v.data.report.outside_period_minutes+' 分钟。填报完整性、实费和收益仍待核证。\n\n缺失、失败、退出和未成熟均保留；不据此证明组织收益。\n\n'+fence+'json\n'+raw+'\n'+fence+'\n';const blob=new Blob([text],{type:kind==='json'?'application/json;charset=utf-8':'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pilot-'+v.id+'-r'+v.data.revision+'.'+kind;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
"""
